WITH valid AS (SELECT id, name, email, country, city, segment, signup_date, credit_limit, age, CASE WHEN city IN ('Bangkok', 'London') THEN 'Tier 1' ELSE 'Other' END AS city_group, COALESCE(city, 'OTHER') AS city_filled FROM customers WHERE city IS DISTINCT FROM 'Chiang Mai') SELECT CASE WHEN credit_limit >= 13000 THEN 'PREMIUM' ELSE 'STANDARD' END AS credit_limit_tier, COUNT_IF(segment = 'SMB') AS smb_events, SUM(CASE WHEN city = 'Berlin' THEN credit_limit ELSE 0 END) AS berlin_credit_limit, COUNT(*) FILTER (WHERE segment = 'Consumer') AS consumer_rows FROM valid GROUP BY CASE WHEN credit_limit >= 13000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY berlin_credit_limit DESC
